import json
from itertools import permutations
from fractions import Fraction

movies = ["horror", "mystery", "romance", "scifi", "western"]
# Slots: (screen, start_hour). Screens 1 and 2 have 7 and 9; screen 3 has 8.
slots = [(1, 7), (1, 9), (2, 7), (2, 9), (3, 8)]
options = {
    "A": ("horror", "screen", 1),
    "B": ("mystery", "start", 7),
    "C": ("mystery", "screen", 2),
    "D": ("scifi", "start", 9),
    "E": ("scifi", "screen", 2),
}

def valid_schedules():
    out = []
    for perm in permutations(range(5)):
        sched = {movies[i]: slots[perm[i]] for i in range(5)}
        scr = {m: sched[m][0] for m in movies}
        st = {m: sched[m][1] for m in movies}
        # Givens
        if not (st["western"] < st["horror"]):
            continue
        if scr["scifi"] == 3:
            continue
        if scr["romance"] == 2:
            continue
        if scr["horror"] == scr["mystery"]:
            continue
        out.append(sched)
    return out

def satisfies_antecedent(sched):
    scr = {m: sched[m][0] for m in movies}
    st = {m: sched[m][1] for m in movies}
    return st["romance"] < st["western"]

def check(sched, opt):
    m, kind, val = options[opt]
    if kind == "screen":
        return sched[m][0] == val
    return sched[m][1] == val

base = valid_schedules()
cond = [s for s in base if satisfies_antecedent(s)]

results = {}
for opt in options:
    results[opt] = all(check(s, opt) for s in cond) if cond else False

must_true = [o for o in sorted(results) if results[o]]
final = must_true[0] if len(must_true) == 1 else "UNSUPPORTED"

evidence = {
    "total_valid_schedules": len(base),
    "schedules_with_antecedent": len(cond),
    "must_be_true": must_true,
}

print(json.dumps({"final_answer": final, "evidence": evidence}, separators=(",", ":")))
